-- Major individual refineries, with Nelson complexity where published.

delete from refineries;
insert into refineries (name, slug, country_name, region_code, operator, capacity_kbd, slate_code, slate_detail, nelson_index, note)
select
  name,
  trim(both '-' from regexp_replace(lower(translate(name, 'áéíóúñçãô', 'aeiouncao')), '[^a-z0-9]+', '-', 'g')),
  country_name, region_code, operator, capacity_kbd, slate_code, slate_detail, nelson_index, note
from jsonb_to_recordset($json$
